import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a cube with edge length {edge_length}, let E be a vertex and A the opposite vertex. On the three edges EF, EH, and EC emanating from E, choose points I, J, and K so that EI = EJ = EK = {offset}. A triangular tunnel is drilled through the cube: its three side walls are the planes parallel to AE that contain the segments IJ, JK, and KI, respectively. Let S be the solid obtained by removing the tunnel, and include the inner walls of the tunnel in the surface area of S. It can be shown that the surface area of S has the form m + n√{radicand}, where m, n are positive integers and {radicand} is squarefree. Determine the value of m + n + {radicand}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate a nontrivial cube instance with integer edge and offset
# Ensure offset is at least 2 and strictly less than edge_length, and avoid the seed's exact (8,2)
# Radicand will be fixed at 6 for this family
for _ in range(1000):
    s = rng.randint(10, 60)  # larger than seed to increase difficulty
    u = rng.randint(2, max(2, s//2))
    if u >= s:
        continue
    if (s, u) == (8, 2):
        continue
    # Ensure the instance is nontrivial: u not too small relative to s, but still feasible
    if u < 2 or s <= 3:
        continue
    # We also prefer that s and u are not both multiples of 4 to avoid trivial scaling from the seed
    if (s % 4 == 0) and (u % 4 == 0):
        continue
    return {
        'edge_length': s,
        'offset': u,
        'radicand': 6
    }
# Fallback in the unlikely case no valid sample is found
return {'edge_length': 12, 'offset': 3, 'radicand': 6}

    def verifier(assign):
# Validate domain constraints and compute m + n + p
# Model: cube of edge length s, equal offsets u on the three edges from E.
# The three planes parallel to AE through IJ, JK, KI bound a triangular prism tunnel.
# For a cube, the projection of each IJ/JK/KI onto the plane perpendicular to AE has the same length as the segment,
# giving lateral area 3*u*s*sqrt(6). The tunnel removes two sets of three congruent right triangles (near E and near A),
# each with total area 3*u*u; hence total removed from outer faces is 6*u*u.
# Original cube surface area is 6*s^2. Thus S = 6*s^2 - 6*u^2 + 3*u*s*sqrt(6) = m + n*sqrt(6), so m=6*s^2-6*u^2, n=3*u*s.
try:
    s = int(assign['edge_length'])
    u = int(assign['offset'])
    p = int(assign['radicand'])
except Exception:
    # Missing or invalid fields
    return False, None  # invalid assignment
# domain checks
if s <= 3:
    return False, None
if u < 1 or u >= s:
    return False, None
if p != 6:
    return False, None
# forbid trivial seed parameters
if (s, u) == (8, 2):
    return False, None
# compute m, n
m = 6 * s * s - 6 * u * u
n = 3 * u * s
# ensure positivity and difficulty constraints
if m <= 0 or n <= 0:
    return False, None
# Answer is m + n + p, an integer
answer = m + n + p
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

